class Solution {
public:
    int minRefuelStops(int target, int startFuel, vector<vector<int>>& stations) {
        priority_queue<int> fuels;
        long long reach = startFuel;
        int i = 0, stops = 0;
        while (reach < target) {
            while (i < (int)stations.size() && stations[i][0] <= reach)
                fuels.push(stations[i++][1]);
            if (fuels.empty()) return -1;
            reach += fuels.top();
            fuels.pop();
            ++stops;
        }
        return stops;
    }
};
